create table wksp_dtesc.sgt_ot_historial (
    id                number generated by default on null as identity minvalue 1 maxvalue 9999999999999999999999999999 increment by 1
    cache 20 noorder nocycle nokeep noscale not null enable,
    ot_id             number not null enable,
    estado_origen_id  number,
    estado_destino_id number,
    tipo_evento       varchar2(30 byte) not null enable,
    detalle           varchar2(2000 byte),
    usuario_evento    varchar2(255 byte) not null enable,
    fecha_evento      timestamp(6) default systimestamp not null enable
);

alter table wksp_dtesc.sgt_ot_historial add primary key ( id )
    using index enable;


